        let tree = fx.tree();
        let main = tree.read(Path::new("src/main.rs")).unwrap();
        assert!(main.contains("fn main"));
        match tree.read(Path::new("target/debug/junk.rs")) {
            Err(SourceError::Ignored(_)) => {}
            other => panic!("expected Ignored, got {other:?}"),
        }
